lemma cayleyBall_inv (S : Set G) {g : G} {n : ℕ}
    (hg : g ∈ CayleyBall S n) :
    g⁻¹ ∈ CayleyBall S n

lemma cayleyBall_mul (S : Set G) {g h : G} {m n : ℕ}
    (hg : g ∈ CayleyBall S m) (hh : h ∈ CayleyBall S n) :
    g * h ∈ CayleyBall S (m + n)

theorem Tengoku.FormalConjectures.exponentialCharacter_memLp {d : ℕ} {Ω : Set (Fin d → ℝ)}
    (hΩ_finite : volume Ω ≠ ⊤) (ξ : Fin d → ℝ) :
    MemLp (exponentialCharacter ξ) 2 (volume.restrict Ω)

theorem IsSidon.insert_ge_max' {A : Finset ℕ} (h : A.Nonempty) (hA : IsSidon (A : Set ℕ)) {s : ℕ}
    (hs : 2 * A.max' h + 1 ≤ s) :
    IsSidon (A ∪ {s})

@[simp]
theorem mem_edges_ofFinset {V : Type} {H : Finset (Finset V)} {hH : Finset.IsThreeUniform H}
    {e : Finset V} : e ∈ (ofFinset H hH).edges ↔ e ∈ H

theorem Int.exists_eq_of_natAbs_sub_le_one (f : ℕ → ℤ)
    (hf : ∀ n, (f (n + 1) - f n).natAbs ≤ 1) {a b : ℕ} (hab : a ≤ b) {t : ℤ}
    (hta : f a ≤ t) (htb : t ≤ f b) : ∃ c, a ≤ c ∧ c ≤ b ∧ f c = t

theorem prod_primeFactors_factorization_apply (n : ℕ) {p : ℕ} (hp : p.Prime) {f : ℕ → ℕ → ℕ}
    (hf : ∀ q n, ¬ q ∣ n → f q n = 0) (hf₀ : ∀ q, f q 0 = 0):
    (∏ q ∈ n.primeFactors, q ^ f q n).factorization p = f p n

theorem cofinite_eq_atTop {α : Type*} [LinearOrder α] [LocallyFiniteOrder α] [OrderBot α]
  [SuccOrder α] [NoMaxOrder α] :
    @cofinite α = atTop

theorem Finset.exists_eq_zero_of_real_sum_lt_card
    {α : Type*} {s : Finset α} {f : α → ℕ}
    (h : (∑ x ∈ s, (f x : ℝ)) < s.card) : ∃ a ∈ s, f a = 0

lemma triangle_area_eq_det (a b c : ℝ²) :
    triangle_area a b c =
    Matrix.det !![a 0, b 0, c 0;
                  a 1, b 1, c 1;
                  1,   1,   1] / 2
